import Foundation
enum Language: String, CaseIterable { case en, fr, de, it, es, pt, zh, ja
    var title: String {
        switch self { case .en: "English"; case .fr: "Français"; case .de: "Deutsch"; case .it: "Italiano"; case .es: "Español"; case .pt: "Português"; case .zh: "中文"; case .ja: "日本語" }
    }
    func text(_ source: String) -> String {
        if let value = Self.exportLocaleLabels[self]?[source] { return value }
        if self == .fr, let value = Self.frenchExportLabels[source] { return value }
        let translations: [String:String]
        switch self { case .en: return source; case .fr: translations = Self.french; case .de: translations = Self.german; case .it: translations = Self.italian; case .es: translations = Self.spanish; case .pt: translations = Self.portuguese; case .zh: translations = Self.chinese; case .ja: translations = Self.japanese }
        let extraTables: [[String:String]] = [
            translations, Self.extended[self] ?? [:], Self.runSettingsTranslations[self] ?? [:], Self.templateCSVTranslations[self] ?? [:], Self.internetConsentTranslations[self] ?? [:], Self.authorizationTranslations[self] ?? [:],
            Self.contactTranslations[self] ?? [:], Self.emailRecipientTranslations[self] ?? [:], Self.reportTranslations[self] ?? [:], Self.reportSelectionTranslations[self] ?? [:], Self.diagnosticTranslations[self] ?? [:], Self.destinationTranslations[self] ?? [:],
            Self.categorySelectionTranslations[self] ?? [:], Self.noCategoryTranslations[self] ?? [:], Self.importCategoryTranslations[self] ?? [:], Self.exportFolderTranslations[self] ?? [:],
            Self.scheduleTranslations[self] ?? [:], Self.menuBarTranslations[self] ?? [:], Self.scheduledPageTranslations[self] ?? [:], Self.scheduleLabelTranslations[self] ?? [:], Self.flowCommentTranslations[self] ?? [:], Self.templateManagementTranslations[self] ?? [:], Self.helpTranslations[self] ?? [:]
        ]
        for table in extraTables { if let translated = table[source] { return translated } }
        if source.hasPrefix("UDP response received ("), source.hasSuffix(" bytes).") {
            let count = source.dropFirst("UDP response received (".count).dropLast(" bytes).".count)
            switch self { case .fr: return "Réponse UDP reçue (\(count) octets)."; case .de: return "UDP-Antwort empfangen (\(count) Byte)."; case .it: return "Risposta UDP ricevuta (\(count) byte)."; case .es: return "Respuesta UDP recibida (\(count) bytes)."; case .pt: return "Resposta UDP recebida (\(count) bytes)."; case .zh: return "已收到 UDP 响应（\(count) 字节）。"; case .ja: return "UDP 応答を受信しました（\(count) バイト）。"; case .en: break }
        }
        if source.hasPrefix("System trust and hostname validation passed. Subject: "),
           let expression = try? NSRegularExpression(pattern: #"^System trust and hostname validation passed\. Subject: (.*?)\. Issuer: (.*?)\. Expires: (.*?)\. SHA-256: (.*)$"#),
           let match = expression.firstMatch(in: source, range: NSRange(source.startIndex..., in: source)) {
            let prefixes: [Language: String] = [.pt: "Validação da confiança do sistema e do nome do anfitrião concluída.", .zh: "系统信任和主机名验证已通过。", .ja: "システムの信頼性とホスト名の検証に成功しました。", .fr: "Validation du certificat système et du nom d’hôte réussie.", .de: "Systemvertrauen und Hostname erfolgreich geprüft.", .es: "Validación de confianza del sistema y del nombre de host correcta.", .it: "Verifica dell’attendibilità del sistema e del nome host riuscita."]
            if let prefix = prefixes[self] {
                func group(_ index: Int) -> String { Range(match.range(at: index), in: source).map { String(source[$0]) } ?? "" }
                return "\(prefix) \(text("subject")): \(group(1)). \(text("issuer")): \(group(2)). \(text("expires")): \(group(3)). SHA-256: \(group(4))"
            }
        }
        return source
    }
